/**
 * DLC Events – Report Engine  (shared by browser HTML and Node GitHub Action)
 *
 * Environment adapters injected at call time via `env` argument:
 *   env.jsPDF       – jsPDF constructor  (window.jspdf.jsPDF  OR  require('jspdf').jsPDF)
 *   env.drawChart   – async (type, data, opts, w, h) => dataURL string
 *   env.jVal        – field accessor from the main HTML (or inline copy below)
 *   env.jParseDdMmDate – date parser
 *
 * Exports (Node) / sets window globals (browser):
 *   dlcGenerateWeeklyReport(allJobs, env)  → { pdf: ArrayBuffer, filename: string }
 *   dlcGenerateMonthlyReport(allJobs, env) → { pdf: ArrayBuffer, filename: string }
 */

(function (root, factory) {
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = factory();          // Node / CommonJS
  } else {
    const api = factory();
    root.dlcGenerateWeeklyReport  = api.dlcGenerateWeeklyReport;
    root.dlcGenerateMonthlyReport = api.dlcGenerateMonthlyReport;
  }
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {

  // ── Colours ────────────────────────────────────────────────────────────────
  const DLC_BLUE    = [43,76,140];
  const DLC_GREEN   = [58,143,111];
  const DLC_RED     = [217,79,65];
  const JT_DRYHIRE  = [197,124,45];
  const JT_RADIOS   = [70,103,227];
  const JT_EVENTS   = [86,159,84];
  const hex = rgb => '#' + rgb.map(x => x.toString(16).padStart(2,'0')).join('');

  // ── Field aliases (mirrors J_ALIASES in the HTML) ─────────────────────────
  const J_ALIASES = {
    'Created on': ['Created on','Created On','created_on','created at','created_at','Created'],
    'Company':    ['Company','company','Client','Client Company'],
    'Job Type':   ['Job Type','Job type','job_type','Type'],
    'Outgoing':   ['Outgoing','outgoing','Outgoing Date','Quote Sent','Sent'],
    'Status':     ['Status','status'],
    'Total':      ['Total','total','Grand Total','Value','Amount'],
  };
  function _jVal(r, f) {
    const keys = J_ALIASES[f] || [f];
    for (const k of keys) {
      if (Object.prototype.hasOwnProperty.call(r,k) && r[k] !== null && r[k] !== undefined && r[k] !== '')
        return r[k];
    }
    return '';
  }
  function _jParseDdMmDate(v) {
    if (!v) return null;
    const s = String(v).trim(); if (!s) return null;
    let m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})(?:\s+.*)?$/);
    if (m) { let [,dd,mm,yy]=m.map(Number); if(yy<100)yy+=2000; const dt=new Date(yy,mm-1,dd); if(dt.getFullYear()===yy&&dt.getMonth()===mm-1&&dt.getDate()===dd)return dt; return null; }
    m = s.match(/^(\d{1,2})[-.](\d{1,2})[-.](\d{2,4})(?:\s+.*)?$/);
    if (m) { let [,dd,mm,yy]=m.map(Number); if(yy<100)yy+=2000; const dt=new Date(yy,mm-1,dd); if(dt.getFullYear()===yy&&dt.getMonth()===mm-1&&dt.getDate()===dd)return dt; return null; }
    m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T\s].*)?$/);
    if (m) { const [,yy,mm,dd]=m.map(Number); const dt=new Date(yy,mm-1,dd); if(dt.getFullYear()===yy&&dt.getMonth()===mm-1&&dt.getDate()===dd)return dt; return null; }
    const dt = new Date(s); return isNaN(dt) ? null : dt;
  }

  // ── Helpers ────────────────────────────────────────────────────────────────
  function dateInRange(dt, mon, sun) {
    if (!dt) return false;
    const d = (dt instanceof Date) ? dt : _jParseDdMmDate(dt);
    if (!d || isNaN(d)) return false;
    return d >= mon && d <= sun;
  }
  function isWon(status) {
    const s = String(status||'').trim().toLowerCase();
    return ['confirmed','dispatched','prepped','part dispatched','returned','returned incomplete','invoiced'].includes(s);
  }
  function jobType(r, jVal) {
    const t = String(jVal(r,'Job Type')||'').trim().toLowerCase();
    if (t === 'dryhire') return 'Dryhire';
    if (t === 'radios')  return 'Radios';
    return 'Events';
  }
  function fmtAED(n) {
    try { return new Intl.NumberFormat('en-AE',{style:'currency',currency:'AED',maximumFractionDigits:0}).format(n); }
    catch(e) { return 'AED '+Math.round(n).toLocaleString(); }
  }

  // ── PDF page structure ─────────────────────────────────────────────────────
  function drawPageHeader(doc, PW, PH, ML, CW, title, subLabel, genDate, logoB64) {
    const H = 22;
    doc.setFillColor(...DLC_BLUE);
    doc.rect(0,0,PW,H,'F');
    try { doc.addImage(logoB64,'PNG',ML,3,26,15); } catch(e){}
    doc.setFont('helvetica','bold'); doc.setFontSize(12); doc.setTextColor(255,255,255);
    doc.text(title, ML+30, 10);
    doc.setFont('helvetica','normal'); doc.setFontSize(7.5); doc.setTextColor(200,215,240);
    doc.text(subLabel, ML+30, 16);
    doc.setFontSize(6.5); doc.setTextColor(180,200,230);
    doc.text(genDate, PW-12, 16, {align:'right'});
    return H + 6;
  }
  function drawPageFooter(doc, PW, PH, footerLabel) {
    doc.setFillColor(...DLC_BLUE);
    doc.rect(0, PH-8, PW, 8, 'F');
    doc.setFont('helvetica','normal'); doc.setFontSize(6); doc.setTextColor(180,200,230);
    doc.text(footerLabel, PW/2, PH-3, {align:'center'});
  }
  function sectionHeader(doc, y, ML, CW, title) {
    doc.setFillColor(...DLC_BLUE);
    doc.roundedRect(ML,y,CW,6.5,1,1,'F');
    doc.setFont('helvetica','bold'); doc.setFontSize(7); doc.setTextColor(255,255,255);
    doc.text(title, ML+3, y+4.5);
    return y + 9;
  }
  function drawTypeLegend(doc, splits, lx0, yStart, totalLabel) {
    const items = [
      {color:JT_DRYHIRE, label:'Dryhire: '+splits.Dryhire},
      {color:JT_RADIOS,  label:'Radios: '+splits.Radios},
      {color:JT_EVENTS,  label:'Events: '+splits.Events},
    ];
    let ly = yStart;
    items.forEach(item => {
      doc.setFillColor(...item.color);
      doc.roundedRect(lx0,ly,3.5,3.5,0.5,0.5,'F');
      doc.setFont('helvetica','bold'); doc.setFontSize(7.5); doc.setTextColor(...DLC_BLUE);
      doc.text(item.label, lx0+6, ly+3);
      ly += 7;
    });
    ly += 2;
    doc.setFont('helvetica','normal'); doc.setFontSize(6); doc.setTextColor(100,116,139);
    doc.text(totalLabel, lx0, ly);
    return ly + 5;
  }


  // ── Embedded DLC logo ──────────────────────────────────────────────────────
  const DLC_LOGO_B64 = 'data:image/png;base64,';


  // ── WEEKLY REPORT ─────────────────────────────────────────────────────────
  async function dlcGenerateWeeklyReport(allJobs, env) {
    const jVal = (env && env.jVal) || _jVal;
    const jParseDdMmDate = (env && env.jParseDdMmDate) || _jParseDdMmDate;
    const drawChart = env.drawChart;
    const jsPDFCtor = env.jsPDF;

    // ── Date range ─────────────────────────────────────────────────────────
    const today = new Date(); today.setHours(0,0,0,0);
    const dow = today.getDay();
    const daysSinceMon = (dow + 6) % 7;
    const thisMon = new Date(today); thisMon.setDate(today.getDate() - daysSinceMon);
    const prevMon = new Date(thisMon); prevMon.setDate(thisMon.getDate() - 7);
    const prevSun = new Date(prevMon); prevSun.setDate(prevMon.getDate() + 6);
    prevSun.setHours(23,59,59,999);

    const fmt = d => d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
    const weekLabel = fmt(prevMon) + ' \u2013 ' + fmt(prevSun);
    const genDate = 'Generated: ' + new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});

    // ── Data ───────────────────────────────────────────────────────────────
    const days = []; for(let i=0;i<7;i++){const d=new Date(prevMon);d.setDate(prevMon.getDate()+i);days.push(d);}
    const quotedByDay = days.map(d => {
      const s=new Date(d);s.setHours(0,0,0,0);
      const e=new Date(d);e.setHours(23,59,59,999);
      return allJobs.filter(r => dateInRange(jParseDdMmDate(jVal(r,'Created on')),s,e)).length;
    });
    const dayLabels = days.map(d => d.toLocaleDateString('en-GB',{weekday:'short'}));
    const totalQuoted = quotedByDay.reduce((a,b)=>a+b,0);

    const outgoingJobs = allJobs.filter(r => dateInRange(jParseDdMmDate(jVal(r,'Outgoing')),prevMon,prevSun));
    const getStatus = r => jVal(r,'Status');
    const wonJobs   = outgoingJobs.filter(r => isWon(getStatus(r)));
    const lostJobs  = outgoingJobs.filter(r => !isWon(getStatus(r)));
    const wonRevenue = wonJobs.reduce((s,r) => s+(Number(String(jVal(r,'Total')||'').replace(/[^\d.-]/g,''))||0), 0);

    function typeSplit(jobs){ const c={Dryhire:0,Radios:0,Events:0}; jobs.forEach(r=>c[jobType(r,jVal)]++); return c; }
    const allTypeSplit = typeSplit(outgoingJobs);
    const wonTypeSplit = typeSplit(wonJobs);

    const companyMap = {};
    outgoingJobs.forEach(r => {
      const co = String(jVal(r,'Company'))||'Unknown';
      if(!companyMap[co]) companyMap[co]={quoted:0,won:0,lost:0};
      companyMap[co].quoted++;
      if(isWon(getStatus(r))) companyMap[co].won++; else companyMap[co].lost++;
    });
    const companyRows = Object.entries(companyMap).sort((a,b)=>b[1].quoted-a[1].quoted);

    // ── Charts ─────────────────────────────────────────────────────────────
    const barImg = await drawChart('bar',{
      labels:dayLabels,
      datasets:[{data:quotedByDay,backgroundColor:hex(DLC_BLUE),borderRadius:3,barPercentage:0.6}]
    },{
      plugins:{legend:{display:false}},
      scales:{
        x:{grid:{display:false},ticks:{color:'#475569',font:{size:10}}},
        y:{grid:{color:'#eee'},ticks:{color:'#475569',font:{size:10},stepSize:1,precision:0},beginAtZero:true}
      }
    },480,160);

    const pieImg = await drawChart('pie',{
      labels:['Won','Lost'],
      datasets:[{data:[wonJobs.length,lostJobs.length],backgroundColor:[hex(DLC_GREEN),hex(DLC_RED)],borderWidth:2,borderColor:'#fff'}]
    },{plugins:{legend:{display:false}}},200,200);

    const makeTypePie = splits => drawChart('pie',{
      labels:['Dryhire','Radios','Events'],
      datasets:[{data:[splits.Dryhire,splits.Radios,splits.Events],backgroundColor:[hex(JT_DRYHIRE),hex(JT_RADIOS),hex(JT_EVENTS)],borderWidth:2,borderColor:'#fff'}]
    },{plugins:{legend:{display:false}}},220,220);
    const allTypeImg = await makeTypePie(allTypeSplit);
    const wonTypeImg = await makeTypePie(wonTypeSplit);

    // ── PDF ────────────────────────────────────────────────────────────────
    const doc = new jsPDFCtor({orientation:'portrait',unit:'mm',format:'a4'});
    const PW=210, PH=297, ML=12, MR=12, CW=PW-ML-MR;
    const FOOTER_H=8, USABLE_H=PH-FOOTER_H;

    let y = drawPageHeader(doc,PW,PH,ML,CW,'Weekly Performance Report',weekLabel,genDate,DLC_LOGO_B64);

    // KPI cards
    const cardW = (CW-6)/3;
    function card(x,cw,val,label){
      doc.setFillColor(255,255,255); doc.setDrawColor(220,228,240);
      doc.roundedRect(x,y,cw,16,1.5,1.5,'FD');
      doc.setFont('helvetica','bold'); doc.setFontSize(13); doc.setTextColor(...DLC_BLUE);
      doc.text(val,x+cw/2,y+8,{align:'center'});
      doc.setFont('helvetica','normal'); doc.setFontSize(6.5); doc.setTextColor(100,116,139);
      doc.text(label,x+cw/2,y+13,{align:'center'});
    }
    card(ML,           cardW, String(totalQuoted),    'Jobs Quoted');
    card(ML+cardW+3,   cardW, String(wonJobs.length), 'Jobs Won');
    card(ML+cardW*2+6, cardW, fmtAED(wonRevenue),     'Est. Revenue');
    y += 21;

    // Bar chart
    y = sectionHeader(doc,y,ML,CW,'JOBS QUOTED \u2014 By Day Created (Previous Week)');
    if(barImg){ const bH=CW*(160/480); doc.addImage(barImg,'PNG',ML,y,CW,bH); y+=bH+3; }

    // Won/Lost pie
    y = sectionHeader(doc,y,ML,CW,'JOBS WON VS LOST \u2014 Outgoing Date Previous Week');
    if(pieImg){
      const pH=34, pW=34;
      doc.addImage(pieImg,'PNG',ML,y,pW,pH);
      const lx=ML+pW+7;
      doc.setFillColor(...DLC_GREEN); doc.roundedRect(lx,y+4,3.5,3.5,0.5,0.5,'F');
      doc.setFont('helvetica','bold'); doc.setFontSize(8); doc.setTextColor(...DLC_BLUE);
      doc.text('Won: '+wonJobs.length,lx+6,y+7);
      doc.setFillColor(...DLC_RED); doc.roundedRect(lx,y+11,3.5,3.5,0.5,0.5,'F');
      doc.text('Lost: '+lostJobs.length,lx+6,y+14);
      const tot=wonJobs.length+lostJobs.length;
      doc.setFont('helvetica','normal'); doc.setFontSize(6.5); doc.setTextColor(100,116,139);
      doc.text('Total: '+tot+' jobs with outgoing in this period',lx,y+21);
      if(tot>0){
        const pct=Math.round(wonJobs.length/tot*100);
        doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(...DLC_GREEN);
        doc.text(pct+'% win rate',lx,y+29);
      }
      y += pH+3;
    }

    // Job type splits
    const halfCW=(CW-4)/2;
    doc.setFillColor(...DLC_BLUE); doc.roundedRect(ML,y,halfCW,6.5,1,1,'F');
    doc.setFont('helvetica','bold'); doc.setFontSize(7); doc.setTextColor(255,255,255);
    doc.text('QUOTED JOB SPLIT',ML+3,y+4.5);
    doc.setFillColor(...DLC_BLUE); doc.roundedRect(ML+halfCW+4,y,halfCW,6.5,1,1,'F');
    doc.text('WON JOB SPLIT',ML+halfCW+4+3,y+4.5);
    y += 9;

    const PIE_D=34;
    if(allTypeImg){ doc.addImage(allTypeImg,'PNG',ML,y,PIE_D,PIE_D); drawTypeLegend(doc,allTypeSplit,ML+PIE_D+4,y+2,'Total: '+outgoingJobs.length+' jobs with outgoing in this period'); }
    if(wonTypeImg){ const rx=ML+halfCW+4; doc.addImage(wonTypeImg,'PNG',rx,y,PIE_D,PIE_D); drawTypeLegend(doc,wonTypeSplit,rx+PIE_D+4,y+2,'Total: '+wonJobs.length+' won jobs with outgoing in this period'); }
    y += PIE_D+6;

    // Company table — overflow to page 2 if needed
    const TBL_HDR_H=6, TBL_ROW_H=5;
    const tblHeight=9+TBL_HDR_H+companyRows.length*TBL_ROW_H+2;
    if(tblHeight > USABLE_H-y){
      drawPageFooter(doc,PW,PH,'DLC Events CRM \u00b7 Confidential \u00b7 '+weekLabel+' \u00b7 Page 1 of 2');
      doc.addPage();
      y = drawPageHeader(doc,PW,PH,ML,CW,'Weekly Performance Report',weekLabel,genDate,DLC_LOGO_B64);
    }

    y = sectionHeader(doc,y,ML,CW,'COMPANIES QUOTED LAST WEEK');
    const colX=[ML,ML+CW*0.57,ML+CW*0.71,ML+CW*0.85];
    const colW=[CW*0.57,CW*0.14,CW*0.14,CW*0.14];

    doc.setFillColor(232,237,245); doc.rect(ML,y,CW,TBL_HDR_H,'F');
    doc.setFont('helvetica','bold'); doc.setFontSize(6.5); doc.setTextColor(71,85,105);
    ['Company','Quotes','Won','Lost'].forEach((h,i)=>{ if(i===0) doc.text(h,colX[0]+2,y+4.2); else doc.text(h,colX[i]+colW[i]/2,y+4.2,{align:'center'}); });
    y += TBL_HDR_H;
    doc.setFont('helvetica','normal'); doc.setFontSize(6.2);

    companyRows.forEach(([co,s],idx)=>{
      if(y+TBL_ROW_H>USABLE_H){
        drawPageFooter(doc,PW,PH,'DLC Events CRM \u00b7 Confidential \u00b7 '+weekLabel+' (continued)');
        doc.addPage();
        y=drawPageHeader(doc,PW,PH,ML,CW,'Weekly Performance Report',weekLabel,genDate,DLC_LOGO_B64);
        doc.setFillColor(232,237,245); doc.rect(ML,y,CW,TBL_HDR_H,'F');
        doc.setFont('helvetica','bold'); doc.setFontSize(6.5); doc.setTextColor(71,85,105);
        ['Company','Quotes','Won','Lost'].forEach((h,i)=>{ if(i===0) doc.text(h,colX[0]+2,y+4.2); else doc.text(h,colX[i]+colW[i]/2,y+4.2,{align:'center'}); });
        y+=TBL_HDR_H; doc.setFont('helvetica','normal'); doc.setFontSize(6.2);
      }
      if(idx%2===0){doc.setFillColor(250,251,253);doc.rect(ML,y,CW,TBL_ROW_H,'F');}
      doc.setTextColor(15,23,42); doc.text(String(co).substring(0,45),colX[0]+2,y+3.5);
      doc.setTextColor(...DLC_BLUE);  doc.text(String(s.quoted),colX[1]+colW[1]/2,y+3.5,{align:'center'});
      doc.setTextColor(...DLC_GREEN); doc.text(String(s.won),   colX[2]+colW[2]/2,y+3.5,{align:'center'});
      doc.setTextColor(...DLC_RED);   doc.text(String(s.lost),  colX[3]+colW[3]/2,y+3.5,{align:'center'});
      y+=TBL_ROW_H;
      doc.setDrawColor(225,230,240); doc.setLineWidth(0.15); doc.line(ML,y,ML+CW,y);
    });

    drawPageFooter(doc,PW,PH,'DLC Events CRM \u00b7 Confidential \u00b7 '+weekLabel);

    const filename = 'DLC_Weekly_Report_' +
      prevMon.toLocaleDateString('en-GB',{day:'2-digit',month:'2-digit',year:'numeric'}).replace(/\//g,'-') + '.pdf';

    return { pdf: doc.output('arraybuffer'), filename };
  }

  // ── MONTHLY REPORT ─────────────────────────────────────────────────────────
  async function dlcGenerateMonthlyReport(allJobs, env) {
    const jVal = (env && env.jVal) || _jVal;
    const jParseDdMmDate = (env && env.jParseDdMmDate) || _jParseDdMmDate;
    const drawChart = env.drawChart;
    const jsPDFCtor = env.jsPDF;

    const today = new Date();
    const firstOfThisMonth = new Date(today.getFullYear(), today.getMonth(), 1);
    const mEnd   = new Date(firstOfThisMonth - 1); mEnd.setHours(23,59,59,999);
    const mStart = new Date(mEnd.getFullYear(), mEnd.getMonth(), 1); mStart.setHours(0,0,0,0);

    const fmt2 = d => d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
    const periodLabel = fmt2(mStart) + ' \u2013 ' + fmt2(mEnd);
    const genDate = 'Generated: ' + new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});

    // ── Data ───────────────────────────────────────────────────────────────
    const daysInMonth = mEnd.getDate();
    const quotedByDay = [], dayLabels = [];
    for(let d=1;d<=daysInMonth;d++){
      const dayStart=new Date(mStart.getFullYear(),mStart.getMonth(),d,0,0,0,0);
      const dayEnd  =new Date(mStart.getFullYear(),mStart.getMonth(),d,23,59,59,999);
      quotedByDay.push(allJobs.filter(r=>dateInRange(jParseDdMmDate(jVal(r,'Created on')),dayStart,dayEnd)).length);
      dayLabels.push(String(d));
    }
    const totalQuoted = quotedByDay.reduce((a,b)=>a+b,0);

    const outgoingJobs = allJobs.filter(r=>dateInRange(jParseDdMmDate(jVal(r,'Outgoing')),mStart,mEnd));
    const getStatus = r => jVal(r,'Status');
    const wonJobs   = outgoingJobs.filter(r=>isWon(getStatus(r)));
    const lostJobs  = outgoingJobs.filter(r=>!isWon(getStatus(r)));
    const wonRevenue = wonJobs.reduce((s,r)=>s+(Number(String(jVal(r,'Total')||'').replace(/[^\d.-]/g,''))||0),0);

    function typeSplit(jobs){ const c={Dryhire:0,Radios:0,Events:0}; jobs.forEach(r=>c[jobType(r,jVal)]++); return c; }
    const allTypeSplit=typeSplit(outgoingJobs);
    const wonTypeSplit=typeSplit(wonJobs);

    const companyMap={};
    outgoingJobs.forEach(r=>{
      const co=String(jVal(r,'Company'))||'Unknown';
      if(!companyMap[co]) companyMap[co]={quoted:0,won:0,lost:0};
      companyMap[co].quoted++;
      if(isWon(getStatus(r))) companyMap[co].won++; else companyMap[co].lost++;
    });
    const companyRows=Object.entries(companyMap).sort((a,b)=>b[1].quoted-a[1].quoted);

    // ── Charts ─────────────────────────────────────────────────────────────
    const barImg=await drawChart('bar',{
      labels:dayLabels,
      datasets:[{data:quotedByDay,backgroundColor:hex(DLC_BLUE),borderRadius:2,barPercentage:0.7}]
    },{
      plugins:{legend:{display:false}},
      scales:{
        x:{grid:{display:false},ticks:{color:'#475569',font:{size:9},maxRotation:0}},
        y:{grid:{color:'#eee'},ticks:{color:'#475569',font:{size:9},stepSize:1,precision:0},beginAtZero:true}
      }
    },800,160);

    const pieImg=await drawChart('pie',{
      labels:['Won','Lost'],
      datasets:[{data:[wonJobs.length,lostJobs.length],backgroundColor:[hex(DLC_GREEN),hex(DLC_RED)],borderWidth:2,borderColor:'#fff'}]
    },{plugins:{legend:{display:false}}},200,200);

    const makeTypePieM=splits=>drawChart('pie',{
      labels:['Dryhire','Radios','Events'],
      datasets:[{data:[splits.Dryhire,splits.Radios,splits.Events],backgroundColor:[hex(JT_DRYHIRE),hex(JT_RADIOS),hex(JT_EVENTS)],borderWidth:2,borderColor:'#fff'}]
    },{plugins:{legend:{display:false}}},220,220);
    const allTypeImg=await makeTypePieM(allTypeSplit);
    const wonTypeImg=await makeTypePieM(wonTypeSplit);

    // ── PDF ────────────────────────────────────────────────────────────────
    const doc=new jsPDFCtor({orientation:'portrait',unit:'mm',format:'a4'});
    const PW=210,PH=297,ML=12,MR=12,CW=PW-ML-MR;
    const FOOTER_H=8,USABLE_H=PH-FOOTER_H;

    function drawMonthHeader(){
      doc.setFillColor(...DLC_BLUE); doc.rect(0,0,PW,22,'F');
      try{ doc.addImage(DLC_LOGO_B64,'PNG',ML,3,26,15); }catch(e){}
      doc.setFont('helvetica','bold'); doc.setFontSize(12); doc.setTextColor(255,255,255);
      doc.text('Monthly Performance Report',ML+30,10);
      doc.setFont('helvetica','normal'); doc.setFontSize(7.5); doc.setTextColor(200,215,240);
      doc.text(periodLabel,ML+30,16);
      doc.setFontSize(6.5); doc.setTextColor(180,200,230);
      doc.text(genDate,PW-MR,16,{align:'right'});
      return 22+6;
    }
    function drawMonthFooter(label){
      doc.setFillColor(...DLC_BLUE); doc.rect(0,PH-8,PW,8,'F');
      doc.setFont('helvetica','normal'); doc.setFontSize(6); doc.setTextColor(180,200,230);
      doc.text(label,PW/2,PH-3,{align:'center'});
    }

    let y=drawMonthHeader();

    // KPI cards
    const cardW=(CW-6)/3;
    function card(x,cw,val,label){
      doc.setFillColor(255,255,255); doc.setDrawColor(220,228,240);
      doc.roundedRect(x,y,cw,16,1.5,1.5,'FD');
      doc.setFont('helvetica','bold'); doc.setFontSize(13); doc.setTextColor(...DLC_BLUE);
      doc.text(val,x+cw/2,y+8,{align:'center'});
      doc.setFont('helvetica','normal'); doc.setFontSize(6.5); doc.setTextColor(100,116,139);
      doc.text(label,x+cw/2,y+13,{align:'center'});
    }
    card(ML,           cardW,String(totalQuoted),   'Jobs Quoted');
    card(ML+cardW+3,   cardW,String(wonJobs.length),'Jobs Won');
    card(ML+cardW*2+6, cardW,fmtAED(wonRevenue),    'Est. Revenue');
    y+=21;

    // Bar chart
    function sectionHdr(title){ y=sectionHeader(doc,y,ML,CW,title); }
    sectionHdr('JOBS QUOTED \u2014 By Day Created (Previous Month)');
    if(barImg){ const bH=CW*(160/800); doc.addImage(barImg,'PNG',ML,y,CW,bH); y+=bH+3; }

    sectionHdr('JOBS WON VS LOST \u2014 Outgoing Date Previous Month');
    if(pieImg){
      const pH=34,pW=34;
      doc.addImage(pieImg,'PNG',ML,y,pW,pH);
      const lx=ML+pW+7;
      doc.setFillColor(...DLC_GREEN); doc.roundedRect(lx,y+4,3.5,3.5,0.5,0.5,'F');
      doc.setFont('helvetica','bold'); doc.setFontSize(8); doc.setTextColor(...DLC_BLUE);
      doc.text('Won: '+wonJobs.length,lx+6,y+7);
      doc.setFillColor(...DLC_RED); doc.roundedRect(lx,y+11,3.5,3.5,0.5,0.5,'F');
      doc.text('Lost: '+lostJobs.length,lx+6,y+14);
      const tot=wonJobs.length+lostJobs.length;
      doc.setFont('helvetica','normal'); doc.setFontSize(6.5); doc.setTextColor(100,116,139);
      doc.text('Total: '+tot+' jobs with outgoing in this period',lx,y+21);
      if(tot>0){
        const pct=Math.round(wonJobs.length/tot*100);
        doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(...DLC_GREEN);
        doc.text(pct+'% win rate',lx,y+29);
      }
      y+=pH+3;
    }

    const halfCW=(CW-4)/2;
    doc.setFillColor(...DLC_BLUE); doc.roundedRect(ML,y,halfCW,6.5,1,1,'F');
    doc.setFont('helvetica','bold'); doc.setFontSize(7); doc.setTextColor(255,255,255);
    doc.text('QUOTED JOB SPLIT',ML+3,y+4.5);
    doc.setFillColor(...DLC_BLUE); doc.roundedRect(ML+halfCW+4,y,halfCW,6.5,1,1,'F');
    doc.text('WON JOB SPLIT',ML+halfCW+4+3,y+4.5);
    y+=9;

    const PIE_D=34;
    if(allTypeImg){ doc.addImage(allTypeImg,'PNG',ML,y,PIE_D,PIE_D); drawTypeLegend(doc,allTypeSplit,ML+PIE_D+4,y+2,'Total: '+outgoingJobs.length+' jobs with outgoing in this period'); }
    if(wonTypeImg){ const rx=ML+halfCW+4; doc.addImage(wonTypeImg,'PNG',rx,y,PIE_D,PIE_D); drawTypeLegend(doc,wonTypeSplit,rx+PIE_D+4,y+2,'Total: '+wonJobs.length+' won jobs with outgoing in this period'); }
    y+=PIE_D+6;

    const TBL_HDR_H=6,TBL_ROW_H=5;
    const tblHeight=9+TBL_HDR_H+companyRows.length*TBL_ROW_H+2;
    if(tblHeight>USABLE_H-y){
      drawMonthFooter('DLC Events CRM \u00b7 Confidential \u00b7 '+periodLabel+' \u00b7 Page 1 of 2');
      doc.addPage(); y=drawMonthHeader();
    }

    sectionHdr('COMPANIES QUOTED THIS MONTH');
    const colX=[ML,ML+CW*0.57,ML+CW*0.71,ML+CW*0.85];
    const colW=[CW*0.57,CW*0.14,CW*0.14,CW*0.14];

    doc.setFillColor(232,237,245); doc.rect(ML,y,CW,TBL_HDR_H,'F');
    doc.setFont('helvetica','bold'); doc.setFontSize(6.5); doc.setTextColor(71,85,105);
    ['Company','Quotes','Won','Lost'].forEach((h,i)=>{ if(i===0) doc.text(h,colX[0]+2,y+4.2); else doc.text(h,colX[i]+colW[i]/2,y+4.2,{align:'center'}); });
    y+=TBL_HDR_H;
    doc.setFont('helvetica','normal'); doc.setFontSize(6.2);

    companyRows.forEach(([co,s],idx)=>{
      if(y+TBL_ROW_H>USABLE_H){
        drawMonthFooter('DLC Events CRM \u00b7 Confidential \u00b7 '+periodLabel+' (continued)');
        doc.addPage(); y=drawMonthHeader();
        doc.setFillColor(232,237,245); doc.rect(ML,y,CW,TBL_HDR_H,'F');
        doc.setFont('helvetica','bold'); doc.setFontSize(6.5); doc.setTextColor(71,85,105);
        ['Company','Quotes','Won','Lost'].forEach((h,i)=>{ if(i===0) doc.text(h,colX[0]+2,y+4.2); else doc.text(h,colX[i]+colW[i]/2,y+4.2,{align:'center'}); });
        y+=TBL_HDR_H; doc.setFont('helvetica','normal'); doc.setFontSize(6.2);
      }
      if(idx%2===0){doc.setFillColor(250,251,253);doc.rect(ML,y,CW,TBL_ROW_H,'F');}
      doc.setTextColor(15,23,42); doc.text(String(co).substring(0,45),colX[0]+2,y+3.5);
      doc.setTextColor(...DLC_BLUE);  doc.text(String(s.quoted),colX[1]+colW[1]/2,y+3.5,{align:'center'});
      doc.setTextColor(...DLC_GREEN); doc.text(String(s.won),   colX[2]+colW[2]/2,y+3.5,{align:'center'});
      doc.setTextColor(...DLC_RED);   doc.text(String(s.lost),  colX[3]+colW[3]/2,y+3.5,{align:'center'});
      y+=TBL_ROW_H;
      doc.setDrawColor(225,230,240); doc.setLineWidth(0.15); doc.line(ML,y,ML+CW,y);
    });

    drawMonthFooter('DLC Events CRM \u00b7 Confidential \u00b7 '+periodLabel);

    const mn = mStart.toLocaleDateString('en-GB',{month:'long',year:'numeric'}).replace(/ /g,'_');
    const filename = 'DLC_Monthly_Report_'+mn+'.pdf';

    return { pdf: doc.output('arraybuffer'), filename };
  }

  return { dlcGenerateWeeklyReport, dlcGenerateMonthlyReport };
});
